"""Pydantic schemas for static and AI findings."""

from typing import List, Optional
from pydantic import BaseModel, Field


class StaticFinding(BaseModel):
    """Normalized finding generated by AST, Ruff, Bandit, or AI analysis."""

    rule_id: str
    tool: str  # 'ruff', 'bandit', 'ast'
    category: str  # 'security', 'quality', 'bug'
    severity: str  # 'CRITICAL', 'HIGH', 'MEDIUM', 'LOW'
    file_path: str
    line_number: int
    end_line_number: Optional[int] = None
    description: str
    code_snippet: Optional[str] = None
    confidence: float = 1.0
    is_in_diff: bool = False


class StaticAnalysisReport(BaseModel):
    """Consolidated static analysis findings report."""

    findings: List[StaticFinding] = Field(default_factory=list)
    total_findings: int = 0
    security_findings_count: int = 0
    quality_findings_count: int = 0
    bug_findings_count: int = 0
    in_diff_findings_count: int = 0
    highest_severity: Optional[str] = None

    def compute_summary(self) -> None:
        """Update metrics based on findings."""
        self.total_findings = len(self.findings)
        self.security_findings_count = sum(1 for f in self.findings if f.category == "security")
        self.quality_findings_count = sum(1 for f in self.findings if f.category == "quality")
        self.bug_findings_count = sum(1 for f in self.findings if f.category == "bug")
        self.in_diff_findings_count = sum(1 for f in self.findings if f.is_in_diff)

        severities = [f.severity for f in self.findings]
        for s in ["CRITICAL", "HIGH", "MEDIUM", "LOW"]:
            if s in severities:
                self.highest_severity = s
                break

